xml.Script:
        Colors[ 0] := 'FFFFFF'; 
        Colors[ 1] := 'F0BB00';
        Colors[ 2] := '599000';
        Colors[ 3] := 'C75C7C';
        Colors[ 4] := '00FFFF';
        Colors[ 5] := '1582EC';
        Colors[ 6] := 'F47E00';
        Colors[ 7] := 'EE5662';
        Colors[ 8] := 'FFEF77';
        Colors[ 9] := '59D685';
        Colors[10] := 'FF64CB';
        Colors[11] := '7B5555';
        Colors[12] := 'BBBBBB';

        sColors[ 0] := '       011000              ';
        sColors[ 1] := '       311220              ';
        sColors[ 2] := '       311220              ';
        sColors[ 3] := '       011227              ';
        sColors[ 4] := '       011227              ';
        sColors[ 5] := '       000220              ';

        sColors[ 6] := '033000 000220 077000 000110';
        sColors[ 7] := '933440 055555 577880 099999';
        sColors[ 8] := '933440 055555 577880 099999';
        sColors[ 9] := '033446 666660 07788a aaaaa0';
        sColors[10] := '033446 666660 07788a aaaaa0';
        sColors[11] := '000440 0cc000 000880 0bb000';

        sColors[12] := '                     0bb000';
        sColors[13] := '                     8bbcc0';
        sColors[14] := '                     8bbcc0';
        sColors[15] := '                     0bbcc4';
        sColors[16] := '                     0bbcc4';
        sColors[17] := '                     000cc0';

        W := 0.5;
        N := 6;
        D := 2 * W / N;

        c := 0;
        for i := 0 to N do
            for j := 0 to N do
                for k := 0 to N do
                    if (i = 0) or (j = 0) or (k = 0) or (i = N) or (j = N) or (k = N) then begin
                        Vx[c] := D * i - W;
                        Vy[c] := D * j - W;
                        Vz[c] := D * k - W;
                        Idx[i,j,k] := IntToStr(c);
                        inc(c);
                    end;

        function GetSIdx(x2, y2, z2);
        begin
            Result := Idx[x2, y2, z2] + ';' + Idx[x2+dx2, y2+dy2, z2+dz2] + ';' + Idx[x2+dx1+dx2, y2+dy1+dy2, z2+dz1+dz2] + ';' + Idx[x2+dx1, y2+dy1, z2+dz1];
        end;

        function GetColor(x3, y3);
        begin
            substr := copy(sColors[y3], x3, 1);
            Result := Colors[HexToInt(substr)];
        end;

        procedure MakeSide(x, y, z, dx1, dy1, dz1, dx2, dy2, dz2, cx, cy);
        // x, y, z - left-top point of side
        // dx1, dy1, dz1 - 1st counting vector
        // dx2, dy2, dz2 - 2nd counting vector
        // cx, cy - left-top letter in sColors
        begin
            for i := 0 to N - 1 do begin
                for j := 0 to N - 1 do begin
                    S[c] := GetSIdx( x + dx1 * i + dx2 * j,  y + dy1 * i + dy2 * j,  z + dz1 * i + dz2 * j);
                    Cl[c] := GetColor(cx + i, cy + j);
                    IE[c] := 15;
                    if i = 0     then IE[c] := IE[c] - 1;
                    if j = N - 1 then IE[c] := IE[c] - 2;
                    if i = N - 1 then IE[c] := IE[c] - 4;
                    if j = 0     then IE[c] := IE[c] - 8;
                    Inc(c);
                end;
            end;
        end;

        c := 0;
        MakeSide( 0, N, N,  1, 0, 0,  0,-1, 0,   8, 0); // up
        MakeSide( 0, 0, N,  1, 0, 0,  0, 0,-1,   8, 6); // face
        MakeSide( 0, N, N,  0,-1, 0,  0, 0,-1,   1, 6); // left
        MakeSide( N, 0, N,  0, 1, 0,  0, 0,-1,  15, 6); // right
        MakeSide( N, N, N, -1, 0, 0,  0, 0,-1,  22, 6); // back
        MakeSide( N, N, 0, -1, 0, 0,  0,-1, 0,  22,12); // bottom
